INSERT INTO public.products (id, category_id, name, slug, description, base_price, status, avg_rating, total_sold) VALUES
('0c506f6f-f21d-4b29-860d-45548f3f43b2', 'a1000000-0000-0000-0000-000000000000', 'Áo thun thời trang - Classic White Crew Neck T-Shirt', 'classic-white-crew-neck-t-shirt-1', 'Elevate your basics with this versatile white crew neck tee. Made from a soft, breathable cotton blend, it offers both comfort and durability. Its sleek, timeless design ensures it pairs well with virtually any outfit. Ideal for layering or wearing on its own, this t-shirt is a must-have staple for every wardrobe. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 975000.0, 'active', 4.5, 10),
('800be4c8-2e74-498b-a2e5-8e2c79f0ed3a', 'a1000000-0000-0000-0000-000000000000', 'Classic White Tee - Timeless Style and Comfort', 'classic-white-tee-timeless-style-and-comfort-2', 'Elevate your everyday wardrobe with our Classic White Tee. Crafted from premium soft cotton material, this versatile t-shirt combines comfort with durability, perfect for daily wear. Featuring a relaxed, unisex fit that flatters every body type, it''s a staple piece for any casual ensemble. Easy to care for and machine washable, this white tee retains its shape and softness wash after wash. Pair it with your favorite jeans or layer it under a jacket for a smart look. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1825000.0, 'active', 4.5, 34),
('4757b25b-b7aa-4fad-86e5-9232eab0d15a', 'a1000000-0000-0000-0000-000000000000', 'Áo thun thời trang - Classic Black T-Shirt', 'classic-black-t-shirt-3', 'Elevate your everyday style with our Classic Black T-Shirt. This staple piece is crafted from soft, breathable cotton for all-day comfort. Its versatile design features a classic crew neck and short sleeves, making it perfect for layering or wearing on its own. Durable and easy to care for, it''s sure to become a favorite in your wardrobe. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 875000.0, 'active', 4.5, 58),
('70a6307a-1da6-4bab-b7ab-1096997c216b', 'a2000000-0000-0000-0000-000000000000', 'Áo sơ mi cao cấp - Classic Grey Hooded Sweatshirt', 'classic-grey-hooded-sweatshirt-4', 'Elevate your casual wear with our Classic Grey Hooded Sweatshirt. Made from a soft cotton blend, this hoodie features a front kangaroo pocket, an adjustable drawstring hood, and ribbed cuffs for a snug fit. Perfect for those chilly evenings or lazy weekends, it pairs effortlessly with your favorite jeans or joggers. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 2250000.0, 'active', 4.5, 10),
('4d8815e6-c5ab-4b7c-bf80-477f7c4d94c8', 'a2000000-0000-0000-0000-000000000000', 'Áo sơ mi cao cấp - Classic Black Hooded Sweatshirt', 'classic-black-hooded-sweatshirt-5', 'Elevate your casual wardrobe with our Classic Black Hooded Sweatshirt. Made from high-quality, soft fabric that ensures comfort and durability, this hoodie features a spacious kangaroo pocket and an adjustable drawstring hood. Its versatile design makes it perfect for a relaxed day at home or a casual outing. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1975000.0, 'active', 4.5, 34),
('e06996fa-e9de-41bb-aaa1-71526ce1e42f', 'a2000000-0000-0000-0000-000000000000', 'Classic Comfort Fit Joggers', 'classic-comfort-fit-joggers-6', 'Discover the perfect blend of style and comfort with our Classic Comfort Fit Joggers. These versatile black joggers feature a soft elastic waistband with an adjustable drawstring, two side pockets, and ribbed ankle cuffs for a secure fit. Made from a lightweight and durable fabric, they are ideal for both active days and relaxed lounging. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 625000.0, 'active', 4.5, 58),
('ad5d81b1-5115-436e-b386-8dc265a38365', 'a2000000-0000-0000-0000-000000000000', 'Classic Comfort Drawstring Joggers', 'classic-comfort-drawstring-joggers-7', 'Experience the perfect blend of comfort and style with our Classic Comfort Drawstring Joggers. Designed for a relaxed fit, these joggers feature a soft, stretchable fabric, convenient side pockets, and an adjustable drawstring waist with elegant gold-tipped detailing. Ideal for lounging or running errands, these pants will quickly become your go-to for effortless, casual wear. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1975000.0, 'active', 4.5, 82),
('931a97e2-1456-4ac9-b6d1-274cabc21405', 'a2000000-0000-0000-0000-000000000000', 'Classic Navy Blue Baseball Cap', 'classic-navy-blue-baseball-cap-8', 'Step out in style with this sleek navy blue baseball cap. Crafted from durable material, it features a smooth, structured design and an adjustable strap for the perfect fit. Protect your eyes from the sun and complement your casual looks with this versatile and timeless accessory. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1525000.0, 'active', 4.5, 106),
('5562684b-2260-4bb0-85f7-f3fcf7638e84', 'a2000000-0000-0000-0000-000000000000', 'Classic Blue Baseball Cap', 'classic-blue-baseball-cap-9', 'Top off your casual look with our Classic Blue Baseball Cap, made from high-quality materials for lasting comfort. Featuring a timeless six-panel design with a pre-curved visor, this adjustable cap offers both style and practicality for everyday wear. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 2150000.0, 'active', 4.5, 130),
('971a7a36-81c6-4ca8-93fc-87c9e85540ff', 'a2000000-0000-0000-0000-000000000000', 'Classic Red Baseball Cap', 'classic-red-baseball-cap-10', 'Elevate your casual wardrobe with this timeless red baseball cap. Crafted from durable fabric, it features a comfortable fit with an adjustable strap at the back, ensuring one size fits all. Perfect for sunny days or adding a sporty touch to your outfit. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 875000.0, 'active', 4.5, 154),
('13ec13e8-eab0-453b-abdd-111c1d92469a', 'a2000000-0000-0000-0000-000000000000', 'Classic Black Baseball Cap', 'classic-black-baseball-cap-11', 'Elevate your casual wear with this timeless black baseball cap. Made with high-quality, breathable fabric, it features an adjustable strap for the perfect fit. Whether you’re out for a jog or just running errands, this cap adds a touch of style to any outfit. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1450000.0, 'active', 4.5, 178),
('ce325556-5d4f-42a3-a47d-f1a854d985b1', 'a2000000-0000-0000-0000-000000000000', 'Classic Olive Chino Shorts', 'classic-olive-chino-shorts-12', 'Elevate your casual wardrobe with these classic olive chino shorts. Designed for comfort and versatility, they feature a smooth waistband, practical pockets, and a tailored fit that makes them perfect for both relaxed weekends and smart-casual occasions. The durable fabric ensures they hold up throughout your daily activities while maintaining a stylish look. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 2100000.0, 'active', 4.5, 202),
('bccff6b2-df01-46c8-b891-70e9bac3cadd', 'a2000000-0000-0000-0000-000000000000', 'Classic High-Waisted Athletic Shorts', 'classic-high-waisted-athletic-shorts-13', 'Stay comfortable and stylish with our Classic High-Waisted Athletic Shorts. Designed for optimal movement and versatility, these shorts are a must-have for your workout wardrobe. Featuring a figure-flattering high waist, breathable fabric, and a secure fit that ensures they stay in place during any activity, these shorts are perfect for the gym, running, or even just casual wear. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1075000.0, 'active', 4.5, 226),
('69ef66bf-04d2-4a0a-9fb9-063e1bfe29f0', 'a3000000-0000-0000-0000-000000000000', 'Classic Red Jogger Sweatpants', 'classic-red-jogger-sweatpants-14', 'Experience ultimate comfort with our red jogger sweatpants, perfect for both workout sessions and lounging around the house. Made with soft, durable fabric, these joggers feature a snug waistband, adjustable drawstring, and practical side pockets for functionality. Their tapered design and elastic cuffs offer a modern fit that keeps you looking stylish on the go. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 2450000.0, 'active', 4.5, 10),
('c6b10e0f-8198-4166-a3db-424a8c783d18', 'a3000000-0000-0000-0000-000000000000', 'Áo sơ mi cao cấp - New Cotton Shirt and pant', 'new-cotton-shirt-and-pant-15', 'Very nice and attractive (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 27500000.0, 'active', 4.5, 34),
('ae9dac2b-277c-4dd9-8ada-2708b0a35c52', 'a4000000-0000-0000-0000-000000000000', 'Classic Red Pullover Hoodie', 'classic-red-pullover-hoodie-16', 'Elevate your casual wardrobe with our Classic Red Pullover Hoodie. Crafted with a soft cotton blend for ultimate comfort, this vibrant red hoodie features a kangaroo pocket, adjustable drawstring hood, and ribbed cuffs for a snug fit. The timeless design ensures easy pairing with jeans or joggers for a relaxed yet stylish look, making it a versatile addition to your everyday attire. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 250000.0, 'active', 4.5, 10),
('55dcaa15-04c0-43e4-b39f-b57260cdab1c', 'c1000000-0000-0000-0000-000000000000', 'Futuristic Holographic Soccer Cleats', 'futuristic-holographic-soccer-cleats-17', 'Step onto the field and stand out from the crowd with these eye-catching holographic soccer cleats. Designed for the modern player, these cleats feature a sleek silhouette, lightweight construction for maximum agility, and durable studs for optimal traction. The shimmering holographic finish reflects a rainbow of colors as you move, ensuring that you''ll be noticed for both your skills and style. Perfect for the fashion-forward athlete who wants to make a statement. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 975000.0, 'active', 4.5, 10),
('ca99cba6-b80f-4639-b44b-95da0fa5942f', 'c1000000-0000-0000-0000-000000000000', 'Rainbow Glitter High Heels', 'rainbow-glitter-high-heels-18', 'Step into the spotlight with these eye-catching rainbow glitter high heels. Designed to dazzle, each shoe boasts a kaleidoscope of shimmering colors that catch and reflect light with every step. Perfect for special occasions or a night out, these stunners are sure to turn heads and elevate any ensemble. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 975000.0, 'active', 4.5, 34),
('926ad6c5-94d4-4f12-b876-25fa8d5353d4', 'c1000000-0000-0000-0000-000000000000', 'Giày sneaker thể thao - Vibrant Runners: Bold Orange & Blue Sneakers', 'vibrant-runners-bold-orange-blue-sneakers-19', 'Step into style with these eye-catching sneakers featuring a striking combination of orange and blue hues. Designed for both comfort and fashion, these shoes come with flexible soles and cushioned insoles, perfect for active individuals who don''t compromise on style. The reflective silver accents add a touch of modernity, making them a standout accessory for your workout or casual wear. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 675000.0, 'active', 4.5, 58),
('1b1711f4-501a-43a7-bb61-75693747f085', 'c1000000-0000-0000-0000-000000000000', 'Giày sneaker thể thao - Vibrant Pink Classic Sneakers', 'vibrant-pink-classic-sneakers-20', 'Step into style with our Vibrant Pink Classic Sneakers! These eye-catching shoes feature a bold pink hue with iconic white detailing, offering a sleek, timeless design. Constructed with durable materials and a comfortable fit, they are perfect for those seeking a pop of color in their everyday footwear. Grab a pair today and add some vibrancy to your step! (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 2100000.0, 'active', 4.5, 82),
('bbd31670-ea81-4211-a3d8-747b48dc9ca4', 'c1000000-0000-0000-0000-000000000000', 'Futuristic Silver and Gold High-Top Sneaker', 'futuristic-silver-and-gold-high-top-sneaker-21', 'Step into the future with this eye-catching high-top sneaker, designed for those who dare to stand out. The sneaker features a sleek silver body with striking gold accents, offering a modern twist on classic footwear. Its high-top design provides support and style, making it the perfect addition to any avant-garde fashion collection. Grab a pair today and elevate your shoe game! (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1700000.0, 'active', 4.5, 106),
('3336bc8e-d97f-46e0-a55d-1b9d7894d457', 'c1000000-0000-0000-0000-000000000000', 'Elegant Patent Leather Peep-Toe Pumps with Gold-Tone Heel', 'elegant-patent-leather-peep-toe-pumps-22', 'Step into sophistication with these chic peep-toe pumps, showcasing a lustrous patent leather finish and an eye-catching gold-tone block heel. The ornate buckle detail adds a touch of glamour, perfect for elevating your evening attire or complementing a polished daytime look. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1325000.0, 'active', 4.5, 130),
('5f3cbae9-a9bf-419b-8321-ee5718820455', 'c1000000-0000-0000-0000-000000000000', 'Elegant Purple Leather Loafers', 'elegant-purple-leather-loafers-23', 'Step into sophistication with our Elegant Purple Leather Loafers, perfect for making a bold statement. Crafted from high-quality leather with a vibrant purple finish, these shoes feature a classic loafer silhouette that''s been updated with a contemporary twist. The comfortable slip-on design and durable soles ensure both style and functionality for the modern man. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 425000.0, 'active', 4.5, 154),
('418cd3c0-a9ff-47a4-b7e0-361d8bca1825', 'c1000000-0000-0000-0000-000000000000', 'Giày thời trang - Classic Blue Suede Casual Shoes', 'classic-blue-suede-casual-shoes-24', 'Step into comfort with our Classic Blue Suede Casual Shoes, perfect for everyday wear. These shoes feature a stylish blue suede upper, durable rubber soles for superior traction, and classic lace-up fronts for a snug fit. The sleek design pairs well with both jeans and chinos, making them a versatile addition to any wardrobe. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 975000.0, 'active', 4.5, 178),
('839fd77e-3e7b-421e-ba80-7797855eca70', 'c1000000-0000-0000-0000-000000000000', 'title-b0b46eb4-6099-4523-bde1-70e9ae9d65b2', 'title-b0b46eb4-6099-4523-bde1-70e9ae9d65b2-25', 'desc-79ff78d2-63ed-4d8f-90cf-3ac639e009c5 (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 22075000.0, 'active', 4.5, 202),
('f4025e6f-d071-4536-aba2-ce4f2d760d05', 'c1000000-0000-0000-0000-000000000000', 'title-e72247e1-8ad8-4b19-ae7e-829b7cf446ff', 'title-e72247e1-8ad8-4b19-ae7e-829b7cf446ff-26', 'desc-3094b9e1-d812-4a61-b65e-fe70f8f07256 (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 15325000.0, 'active', 4.5, 226),
('a42b75e2-f088-44ba-8d39-db91ef02694b', 'c2000000-0000-0000-0000-000000000000', 'Sandal quai ngang - Chic Summer Denim Espadrille Sandals', 'chic-summer-denim-espadrille-sandals-27', 'Step into summer with style in our denim espadrille sandals. Featuring a braided jute sole for a classic touch and adjustable denim straps for a snug fit, these sandals offer both comfort and a fashionable edge. The easy slip-on design ensures convenience for beach days or casual outings. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 825000.0, 'active', 4.5, 10),
('800159d6-cf1d-4c68-b5b8-b60ad22352c5', 'c3000000-0000-0000-0000-000000000000', 'Giày boots cá tính - Futuristic Chic High-Heel Boots', 'futuristic-chic-high-heel-boots-28', 'Elevate your style with our cutting-edge high-heel boots that blend bold design with avant-garde aesthetics. These boots feature a unique color-block heel, a sleek silhouette, and a versatile light grey finish that pairs easily with any cutting-edge outfit. Crafted for the fashion-forward individual, these boots are sure to make a statement. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 900000.0, 'active', 4.5, 10),
('b2fa4eb7-c69c-4489-a7ed-6f8f42540ced', 'd1000000-0000-0000-0000-000000000000', 'Túi xách cao cấp - Chic Transparent Fashion Handbag', 'chic-transparent-fashion-handbag-29', 'Elevate your style with our Chic Transparent Fashion Handbag, perfect for showcasing your essentials with a clear, modern edge. This trendy accessory features durable acrylic construction, luxe gold-tone hardware, and an elegant chain strap. Its compact size ensures you can carry your day-to-day items with ease and sophistication. (Sản phẩm nhập khẩu chính hãng chất lượng cao, phân phối độc quyền bởi Shofy Fashion).', 1525000.0, 'active', 4.5, 10);
